import { classErrorMessage, useClass, useClasses, useSaveClass, type ClassCreateRequest, type ClassUpdateRequest } from "@/lib/classes-api";
import { sectionErrorMessage, useSaveSection, useSections, useSectionsByClass, type SectionCreateRequest, type SectionUpdateRequest } from "@/lib/sections-api";
import { subjectErrorMessage, useDeleteSubject, useSaveSubject, useSubject, useSubjectsByClass, type SubjectCreateRequest, type SubjectUpdateRequest } from "@/lib/subjects-api";
