  if (classes.isError) return <Empty title="Could not load classes" detail={classErrorMessage(classes.error, "Could not load classes.")} />;
  const item = editing ? sections.data?.find((section) => section.id === id) : undefined;
  if (editing && !item) return <Empty title="Section not found" detail="The requested section could not be found." />;
  const submit = (values: { name: string; classId: string }) => { const payload: SectionCreateRequest | SectionUpdateRequest = editing ? { name: values.name } : { name: values.name, classId: values.classId }; save.mutate(payload, { onSuccess: (saved) => { toast({ title: editing ? "Section updated" : "Section created", description: "The section record is ready." }); setLocation(saved?.id ? `/sections/${saved.id}` : "/sections"); }, onError: (error) => toast({ title: "Could not save section", description: sectionErrorMessage(error, "Could not save section.") }) }); };
  return <><button className="back-link page-back" onClick={() => setLocation(id ? `/sections/${id}` : "/sections")}><ArrowLeft size={15} />Back to Sections</button><PageHeader eyebrow={editing ? "Edit academic setup" : "New academic setup"} title={editing ? "Edit section" : "Add section"} description="Keep each section connected to its parent class." /><form className="form-card" onSubmit={form.handleSubmit(submit, () => toast({ title: "Check the form", description: "A few required fields still need your attention." }))}><div className="form-grid"><Field form={form} name="name" label="Section name" /><SelectField form={form} name="classId" label="Parent class" options={(classes.data || []).map((schoolClass) => [schoolClass.id, schoolClass.name])} disabled={editing} /></div><div className="form-actions"><AppButton type="button" variant="ghost" onClick={() => setLocation(id ? `/sections/${id}` : "/sections")}>Cancel</AppButton><AppButton type="submit" disabled={save.isPending}>{save.isPending ? "Saving…" : editing ? "Save changes" : "Create section"}<ArrowRight size={16} /></AppButton></div></form></>;
