  if (sections.isError) return <Empty title="Could not load sections" detail={sectionErrorMessage(sections.error, "Could not load sections.")} />;
  if (classes.isError) return <Empty title="Could not load classes" detail={classErrorMessage(classes.error, "Could not load classes.")} />;
