  return <><button className="back-link page-back" onClick={() => setLocation("/sections")}><ArrowLeft size={15} />Back to Sections</button><div className="detail-header"><div className="detail-title"><div className="hierarchy-emblem"><GraduationCap size={25} /></div><div><div className="eyebrow">Academic hierarchy</div><h1>{item.name}</h1><p>{parent?.name || "Class unavailable"}</p></div></div>{hasPermission(session.role, "CLASS_UPDATE") && <Link href={`/sections/${id}/edit`} className="inline-flex h-10 items-center gap-2 rounded-lg border border-border bg-card px-4 text-sm font-semibold"><Settings2 size={15} />Edit</Link>}</div><div className="detail-grid"><section className="panel detail-panel"><div className="panel-head"><div><div className="eyebrow">Connected record</div><h2>Section</h2></div></div><div className="detail-fields"><div className="detail-field"><span>Section name</span><strong>{item.name}</strong></div><div className="detail-field"><span>Class</span><strong>{parent?.name || "—"}</strong></div></div></section></div></>;
